/**
 * Component: Responsive Gradient Navbar
 * Author: @jugendra-gangwar (https://tailwindflex.com/@jugendra-gangwar)
 * Source: https://tailwindflex.com/@jugendra-gangwar/responsive-gradient-navbar
 * Attribution: Créé par @jugendra-gangwar sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function ResponsiveGradientNavbar() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">

<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Responsive Gradient Navbar | Tailwind CSS</title>

  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Sora:wght@300;400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --brand-gradient: linear-gradient(314deg, #2A3390 2.37%, #3671CA 54.49%, #0CDCF6 98.53%);
    }

    html {
      -webkit-text-size-adjust: 100%;
    }

    body {
      font-family: "Sora", sans-serif;
      overflow-x: hidden;
    }

    .gradient-text {
      background: var(--brand-gradient);
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
    }

    .gradient-bg {
      background: var(--brand-gradient);
    }

    .contact-button {
      isolation: isolate;
    }

    .contact-button::before {
      content: "";
      position: absolute;
      inset: 0;
      z-index: -1;
      background: var(--brand-gradient);
      transform: scaleX(0);
      transform-origin: left;
      transition: transform .35s ease;
    }

    .contact-button:hover::before,
    .contact-button:focus-visible::before {
      transform: scaleX(1);
    }

    .nav-link::after {
      content: "";
      position: absolute;
      left: 0;
      top: calc(100% + 7px);
      height: 3px;
      width: 0;
      border-radius: 999px;
      background: var(--brand-gradient);
      transition: width .25s ease;
    }

    .nav-link:hover::after,
    .nav-link:focus-visible::after,
    .nav-link[aria-current="page"]::after {
      width: 100%;
    }

    #mobile-menu {
      visibility: hidden;
      transition: visibility 0s linear .35s;
    }

    #mobile-menu.is-open {
      visibility: visible;
      transition-delay: 0s;
    }

    #menu-overlay {
      opacity: 0;
      transition: opacity .35s ease;
    }

    #mobile-menu.is-open #menu-overlay {
      opacity: 1;
    }

    #menu-panel {
      transform: translateX(100%);
      transition: transform .35s cubic-bezier(.32, .72, 0, 1);
      height: 100vh;
      height: 100dvh;
      padding-bottom: max(1.5rem, env(safe-area-inset-bottom));
    }

    #mobile-menu.is-open #menu-panel {
      transform: translateX(0);
    }

    .side-item {
      opacity: 0;
      transform: translateX(24px);
      transition: opacity .35s ease, transform .35s ease;
    }

    #mobile-menu.is-open .side-item {
      opacity: 1;
      transform: translateX(0);
    }

    #mobile-menu.is-open .side-item:nth-child(1) {
      transition-delay: .10s;
    }

    #mobile-menu.is-open .side-item:nth-child(2) {
      transition-delay: .15s;
    }

    #mobile-menu.is-open .side-item:nth-child(3) {
      transition-delay: .20s;
    }

    #mobile-menu.is-open .side-item:nth-child(4) {
      transition-delay: .25s;
    }

    #mobile-menu.is-open .side-item:nth-child(5) {
      transition-delay: .30s;
    }

    #mobile-menu.is-open .side-item:nth-child(6) {
      transition-delay: .38s;
    }

    @media (prefers-reduced-motion: reduce) {

      *,
      *::before,
      *::after {
        transition-duration: .01ms !important;
        transition-delay: 0s !important;
        animation-duration: .01ms !important;
      }
    }
  </style>
</head>

<body class="min-h-screen bg-[#080B18] text-white">
  <header class="sticky top-0 z-50 px-3 pt-3 sm:px-6 sm:pt-5">
    <div class="mx-auto w-full max-w-[1188px]">
      <nav aria-label="Main navigation" class="relative">
        <div
          class="flex w-full items-center justify-between gap-3 rounded-lg border-2 border-white/10 bg-[#0d1124]/80 p-2 backdrop-blur-md sm:gap-6 sm:p-2.5">
          <a href="/" aria-label="Go to homepage"
            class="shrink-0 pl-1 text-lg font-bold tracking-tight sm:text-xl">Tailwind<span
              class="gradient-text">Flex</span></a>
          <div class="hidden items-center gap-6 xl:gap-8 lg:flex" aria-label="Primary links">
            <a class="nav-link relative w-fit text-base font-light leading-normal opacity-100 transition-opacity hover:opacity-100"
              aria-current="page" href="/">Home</a>
            <a class="nav-link relative w-fit text-base font-light leading-normal opacity-70 transition-opacity hover:opacity-100"
              href="/about">About</a>
            <a class="nav-link relative w-fit text-base font-light leading-normal opacity-70 transition-opacity hover:opacity-100"
              href="/services">Services</a>
            <a class="nav-link relative w-fit text-base font-light leading-normal opacity-70 transition-opacity hover:opacity-100"
              href="/portfolio">Portfolio</a>
            <a class="nav-link relative w-fit text-base font-light leading-normal opacity-70 transition-opacity hover:opacity-100"
              href="/courses">Courses</a>
          </div>
          <div class="flex shrink-0 items-center justify-end gap-2 sm:gap-3">
            <a href="/contact"
              class="contact-button relative hidden h-10 w-[110px] items-center justify-center overflow-hidden rounded-lg border border-white/15 bg-white/[0.04] text-center text-sm font-normal transition-colors hover:border-transparent sm:inline-flex sm:h-11 sm:w-[121px]"><span
                class="relative z-10">Contact Us</span></a>
            <button id="menu-open" type="button" aria-label="Open menu" aria-controls="mobile-menu"
              aria-expanded="false"
              class="gradient-bg flex h-10 w-10 items-center justify-center rounded-md transition active:scale-95 sm:h-11 sm:w-11 lg:hidden">
              <svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" class="h-5 w-5" viewBox="0 0 24 24"
                fill="none" stroke="currentColor" stroke-width="2">
                <path stroke-linecap="round" d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            </button>
          </div>
        </div>
      </nav>
    </div>
  </header>

  <div id="mobile-menu" class="fixed inset-0 z-[60] lg:hidden" aria-hidden="true">
    <div id="menu-overlay" class="absolute inset-0 bg-black/60 backdrop-blur-sm"></div>
    <aside id="menu-panel" role="dialog" aria-modal="true" aria-label="Mobile navigation"
      class="absolute right-0 top-0 flex w-[85%] max-w-[360px] flex-col overflow-y-auto border-l border-white/10 bg-[#0b0f22] p-5 shadow-2xl sm:p-6">
      <div class="flex items-center justify-between">
        <a href="/" aria-label="Go to homepage" class="text-lg font-bold tracking-tight sm:text-xl">Tailwind<span
            class="gradient-text">Flex</span></a>
        <button id="menu-close" type="button" aria-label="Close menu"
          class="rounded-full border border-white/30 p-2.5 transition hover:rotate-90 hover:border-white active:scale-95">
          <svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" viewBox="0 0 24 24"
            fill="currentColor">
            <path
              d="M18.3 5.7a1 1 0 0 0-1.4-1.4L12 9.6 7.1 4.3a1 1 0 0 0-1.4 1.4L10.6 12l-4.9 4.9a1 1 0 1 0 1.4 1.4l4.9-4.9 4.9 4.9a1 1 0 1 0 1.4-1.4L13.4 12z" />
          </svg>
        </button>
      </div>

      <div class="my-6 h-px w-full bg-white/10"></div>

      <ul class="flex flex-col gap-1 text-lg">
        <li class="side-item"><a class="nav-link relative my-3 block w-fit py-1" aria-current="page" href="/">Home</a>
        </li>
        <li class="side-item"><a class="nav-link relative my-3 block w-fit py-1 opacity-75 hover:opacity-100"
            href="/about">About</a></li>
        <li class="side-item"><a class="nav-link relative my-3 block w-fit py-1 opacity-75 hover:opacity-100"
            href="/services">Services</a></li>
        <li class="side-item"><a class="nav-link relative my-3 block w-fit py-1 opacity-75 hover:opacity-100"
            href="/portfolio">Portfolio</a></li>
        <li class="side-item"><a class="nav-link relative my-3 block w-fit py-1 opacity-75 hover:opacity-100"
            href="/courses">Courses</a></li>
      </ul>

      <div class="side-item mt-auto pt-8">
        <a href="/contact"
          class="gradient-bg flex w-full items-center justify-center rounded-lg px-5 py-3.5 text-sm font-semibold transition active:scale-[.98]">Contact
          Us</a>
      </div>
    </aside>
  </div>

  <main class="mx-auto flex min-h-[65vh] max-w-4xl flex-col items-center justify-center px-4 text-center sm:px-6">
  </main>


</body>

</html>" }} />
  );
}
